-- Pilot-only: account-verified, tenant-isolated membership linking.
-- Staff chooses the member's email and sends the generic app URL; no ephemeral
-- code or QR is generated by the management app.
create or replace function public.socio_link_by_verified_email()
returns integer language plpgsql security definer set search_path to ''
as $function$
declare v_user uuid := (select auth.uid());
        v_email text;
        v_linked integer := 0;
begin
 select lower(btrim(u.email)) into v_email
 from auth.users u where u.id=v_user and u.email_confirmed_at is not null;
 if v_email is null or v_email='' or exists (
   select 1 from public.user_roles r where r.user_id=v_user
 ) then
   raise exception 'SOCIO_ACCOUNT_NOT_AUTHORIZED' using errcode='42501';
 end if;
 -- Each eligible member must be unique within their club for this email;
 -- skip duplicates or pre-owned cards instead of choosing a random identity.
 insert into public.socio_membership_links(auth_user_id,club_id,member_id,status,verified_at)
 select v_user,m.club_id,m.id,'verified',now()
 from public.members m
 join public.clubs c on c.id=m.club_id and c.active
 join public.socio_member_cards card on card.club_id=m.club_id and card.member_id=m.id
 where lower(btrim(m.email))=v_email
   and m.expires_at >= current_date
   and card.active and card.revoked_at is null
   and (select count(*)
        from public.members other
        where other.club_id=m.club_id
          and lower(btrim(other.email))=v_email)=1
   and not exists (
     select 1 from public.socio_membership_links l
     where l.club_id=m.club_id and l.member_id=m.id
   )
 on conflict (club_id,member_id) do nothing;
 get diagnostics v_linked=row_count;
 return v_linked;
end;
$function$;
revoke all on function public.socio_link_by_verified_email() from public, anon;
grant execute on function public.socio_link_by_verified_email() to authenticated;
